adminUpstreamsRoute.post('/', async (c) => {
  const parsed = await parseJsonBody(c, CreateUpstreamRequest)
  if (!parsed.ok) return parsed.res
  const input = parsed.data
  // Self-loop guard: an upstream must not point back at this ctxlayer
  // deployment (host+port match against PUBLIC_BASE_URL), or the proxy
  // would call into itself. Enforced here, not in the shared schema,
  // which can't see env.
  if (isSameOrigin(input.url, c.env.PUBLIC_BASE_URL)) {
    return c.json({ error: 'self_loop', message: 'URL must not point at this ctxlayer instance' }, 400)
  }
  if (oauthEndpointSelfLoop(input.authConfig, c.env)) {
    return c.json(
      { error: 'self_loop', message: 'OAuth endpoints must not point at this ctxlayer instance' },
      400
    )
  }
  try {
    const row = await createUpstream(c.env, {
      slug: input.slug,
      displayName: input.displayName,
      transport: input.transport,
      url: input.url,
      authStrategy: input.authStrategy,
      authConfig:
        (await prepareOAuthSecret(
          dropLegacyDcrMirror(clampTimeouts(input.authConfig)),
          c.env,
          undefined
        )) ?? {},
      enabled: input.enabled ?? true
    })
    // For unauth (`none`) upstreams there's nothing to wait for —
    // warm the catalogue immediately so the admin sees a real tool
    // count in the drawer instead of zero. user_bearer / user_oauth /
    // shared_bearer all need credentials before refresh is meaningful;
    // those are warmed on connect (PUT credentials / OAuth callback).
    if (input.authStrategy === 'none') {
      c.executionCtx.waitUntil(
        warmCatalogueAndLog(c.env, {
          upstreamId: row.id,
          slug: row.slug,
          bearerToken: null,
          okContext: 'on create (auth=none)',
          failLabel: 'post-create refresh'
        })
      )
    }
    const hydrated = await adminRowFor(c.env, row.id, c.get('user').userId)
    await audit(c.env, {
      actorId: c.get('user').userId,
      action: 'upstream.create',
      target: row.id,
      meta: { slug: row.slug }
    })
    return c.json(hydrated, 201)
  } catch (err) {
    if (isUniqueViolation(err)) return c.json({ error: 'slug_taken' }, 409)
    throw err
  }
})

adminUpstreamsRoute.patch('/:id', async (c) => {
  const id = c.req.param('id')
  const current = await getUpstreamById(c.env, id)
  if (!current) return notFound(c)
  const parsed = await parseJsonBody(c, UpdateUpstreamRequest)
  if (!parsed.ok) return parsed.res
  if (parsed.data.url && isSameOrigin(parsed.data.url, c.env.PUBLIC_BASE_URL)) {
    return c.json({ error: 'self_loop', message: 'URL must not point at this ctxlayer instance' }, 400)
  }
  if (oauthEndpointSelfLoop(parsed.data.authConfig, c.env)) {
    return c.json(
      { error: 'self_loop', message: 'OAuth endpoints must not point at this ctxlayer instance' },
      400
    )
  }
  const currentConfig = parseAuthConfig(current.auth_config)
  // The DCR registration stays valid only for the same server under the
  // same strategy — see preserveDcrClient.
  const keepDcrClient =
    (parsed.data.authStrategy ?? current.auth_strategy) === 'user_oauth' &&
    (parsed.data.url === undefined || parsed.data.url === current.url)
  await patchUpstream(c.env, id, {
    ...parsed.data,
    authConfig: preserveDcrClient(
      await prepareOAuthSecret(
        dropLegacyDcrMirror(clampTimeouts(parsed.data.authConfig)),
        c.env,
        currentConfig
      ),
      currentConfig,
      keepDcrClient
    )
  })
  await audit(c.env, {
    actorId: c.get('user').userId,
    action: 'upstream.update',
    target: id,
    meta: { fields: Object.keys(parsed.data) }
  })
  return new Response(null, { status: 204 })
})

adminUpstreamsRoute.delete('/:id', async (c) => {
  const id = c.req.param('id')
  const row = await getUpstreamById(c.env, id)
  await deleteUpstream(c.env, id)
  if (row) {
    await audit(c.env, {
      actorId: c.get('user').userId,
      action: 'upstream.delete',
      target: id,
      meta: { slug: row.slug }
    })
  }
  return new Response(null, { status: 204 })
})

// Replace the visibility rule-set for one upstream in a single batch.
adminUpstreamsRoute.put('/:id/visibility', async (c) => {
  const id = c.req.param('id')
  if (!(await getUpstreamById(c.env, id))) return notFound(c)
  const parsed = await parseJsonBody(c, ReplaceVisibilityRequest)
  if (!parsed.ok) return parsed.res
  await replaceVisibility(c.env, id, parsed.data.rules)
  await audit(c.env, {
    actorId: c.get('user').userId,
    action: 'upstream.visibility_set',
    target: id,
    meta: { rules: parsed.data.rules.length }
  })
  return new Response(null, { status: 204 })
})

/**
 * Per-tool ACL for one upstream. GET returns the current rule sets
 * grouped by tool, each flagged `orphaned` when its tool_name is no
 * longer in the cached catalogue (an upstream rename strands the rule —
 * surfaced, never silently dropped, or the renamed tool re-opens). A
 * tool absent from this list has no rules and inherits upstream
 * visibility (open to anyone who can see the upstream).
 */
adminUpstreamsRoute.get('/:id/tool-access', async (c) => {
  const id = c.req.param('id')
  if (!(await getUpstreamById(c.env, id))) return notFound(c)
  const [rows, tools] = await Promise.all([
    listToolAccessForUpstream(c.env, id),
    listCachedTools(c.env, id)
  ])
  const live = new Set(tools.map((t) => t.tool_name))
  const byTool = new Map<string, ToolAccessRule[]>()
  for (const r of rows) {
    const list = byTool.get(r.tool_name) ?? []
    list.push({
      principalKind: r.principal_kind,
      principalId: r.principal_kind === 'everyone' ? null : r.principal_id
    })
    byTool.set(r.tool_name, list)
  }
  const entries: ToolAccessEntry[] = [...byTool.entries()].map(([toolName, rules]) => ({
    toolName,
    rules,
    orphaned: !live.has(toolName)
  }))
  const body: UpstreamToolAccessResponse = { upstreamId: id, entries }
  return c.json(body)
})

// Replace the ENTIRE rule set for one tool. Empty `rules` reverts the
// tool to inherit (open).
adminUpstreamsRoute.put('/:id/tool-access', async (c) => {
  const id = c.req.param('id')
  if (!(await getUpstreamById(c.env, id))) return notFound(c)
  const parsed = await parseJsonBody(c, ReplaceToolAccessRequest)
  if (!parsed.ok) return parsed.res
  await replaceToolAccessForTool(c.env, id, parsed.data.toolName, parsed.data.rules)
  await audit(c.env, {
    actorId: c.get('user').userId,
    action: 'upstream.tool_access_set',
    target: id,
    meta: { tool: parsed.data.toolName, rules: parsed.data.rules.length }
  })
  return new Response(null, { status: 204 })
})

/**
 * Read the cached tool list for an upstream. Backs the expand-row
 * drill-down on /app/admin/upstreams. Read-only; doesn't trigger a
 * refresh. If the cache is empty (newly created, never warmed) the
 * `tools` array is empty and the admin can click the existing
 * "Refresh tools" button to populate it.
 */
adminUpstreamsRoute.get('/:id/tools', async (c) => {
  const id = c.req.param('id')
  const row = await getUpstreamById(c.env, id)
  if (!row) return notFound(c)
  // Admin view sees drafts as well as published; non-admin user route
  // (api/upstreams.ts) only sees published.
  return c.json(
    await buildUpstreamToolsPayload(c.env, { id, slug: row.slug }, { includeDrafts: true })
  )
})

/**
 * Admin-triggered catalogue refresh. Uses the calling admin's own
 * credentials for upstreams that need them (paste-bearer for
 * `user_bearer`, OAuth tokens for `user_oauth`, no creds for `none`).
 * If the admin hasn't connected the upstream on `/upstreams` yet, we
 * tell them so they can connect once and reuse the refresh button
 * thereafter. The per-user MCP session refresh path is still available
 * as a fallback for non-admin users on session init.
 */
adminUpstreamsRoute.post('/:id/refresh-tools', async (c) => {
  const id = c.req.param('id')
  const row = await getUpstreamById(c.env, id)
  if (!row) return notFound(c)
  let conn: ReturnType<typeof toUpstreamConnection>
  try {
    conn = toUpstreamConnection(row)
  } catch {
    return c.json({ error: 'unsupported_transport' }, 400)
  }
  const userId = c.get('user').userId
  const bearer = await resolveUserUpstreamBearer(c.env, row, conn, userId)
  if (conn.authStrategy !== 'none' && bearer === null) {
    return c.json(
      {
        error: 'admin_not_connected',
        hint: `Connect this upstream on /upstreams as ${conn.authStrategy}, then try again.`
      },
      400
    )
  }
  // `force` bypasses the catalogue shrink-guard: the admin button is the
  // deliberate path for applying a genuine large tool removal.
  const result = await refreshCatalogueForConnection(c.env, conn, bearer, { force: true })
  if (!result.ok) {
    return c.json({ error: 'refresh_failed', message: result.message }, 502)
  }
  const body: RefreshToolsResponse = {
    upstreamId: id,
    slug: result.slug,
    toolsCount: result.toolsCount,
    cachedAt: result.cachedAt
  }
  return c.json(body)
})

/**
 * Set / replace the shared bearer token for a `shared_bearer` upstream.
 * The whole org uses this token for outbound calls — there's no
 * per-user storage. Caller's user id goes in `created_by` for the
 * audit trail. After the upsert, warm the catalogue in waitUntil
 * (admin doesn't need to click Refresh).
 */
adminUpstreamsRoute.put('/:id/shared-credentials', async (c) => {
  const id = c.req.param('id')
  const row = await getUpstreamById(c.env, id)
  if (!row) return notFound(c)
  if (row.auth_strategy !== 'shared_bearer') {
    return c.json({ error: 'auth_strategy_mismatch', expected: 'shared_bearer' }, 400)
  }
  const parsed = await parseJsonBody(c, PasteBearerRequest)
  if (!parsed.ok) return parsed.res
  const actor = c.get('user')
  const sealed = await seal(parsed.data.token, c.env.ENCRYPTION_KEY)
  await upsertSharedCredential(c.env, id, {
    kind: 'bearer',
    ciphertext: sealed.ciphertext,
    iv: sealed.iv,
    keyVersion: sealed.keyVersion,
    createdBy: actor.userId
  })
  await audit(c.env, {
    actorId: actor.userId,
    action: 'upstream.shared_bearer_set',
    target: id,
    meta: { slug: row.slug }
  })
  // Warm catalogue immediately so the admin sees toolsCount populate
  // without a manual Refresh click.
  c.executionCtx.waitUntil(
    warmCatalogueAndLog(c.env, {
      upstreamId: id,
      slug: row.slug,
      bearerToken: parsed.data.token,
      okContext: 'after shared-bearer set',
      failLabel: 'shared-bearer refresh'
    })
  )
  return new Response(null, { status: 204 })
})

adminUpstreamsRoute.delete('/:id/shared-credentials', async (c) => {
  const id = c.req.param('id')
  const row = await getUpstreamById(c.env, id)
  if (!row) return notFound(c)
  const actor = c.get('user')
  await deleteSharedCredential(c.env, id)
  await audit(c.env, {
    actorId: actor.userId,
    action: 'upstream.shared_bearer_clear',
    target: id,
    meta: { slug: row.slug }
  })
  return new Response(null, { status: 204 })
})

import { useCallback, useEffect, useState } from 'react'
import { Alert, Drawer, Stack, Text } from '@mantine/core'
import type { AdminUpstreamRow, ProductRef, RoleRef, TeamRef } from '@ctxlayer/shared'
import {
  adminDeleteSharedCredentials,
  adminDeleteUpstream,
  adminPatchUpstream,
  adminPutSharedCredentials,
  adminPutUpstreamVisibility,
  adminRefreshUpstreamTools,
  deleteUpstreamCredentials,
  fetchAdminUpstream,
  fetchProducts,
  fetchRoles,
  fetchTeams,
  putUpstreamCredentials
} from '../../../lib/api'
import { useBusyAction } from '../../../lib/use-busy'
import { useDrawerConfirm } from '../../../lib/dialogs'
import { explain } from './helpers'
import { ConnectionSection } from './ConnectionSection'
import { DetailsSection } from './DetailsSection'
import { ToolsCacheSection } from './ToolsCacheSection'
import { ToolAccessSection } from './ToolAccessSection'
import { VisibilitySection } from './VisibilitySection'

export function UpstreamDrawer({
  upstreamId,
  onClose,
  onChanged,
  onDeleted
}: {
  upstreamId: string
  onClose: () => void
  onChanged: () => void
  onDeleted: () => void
}) {
  const { hidden, confirm, reveal } = useDrawerConfirm()
  const [row, setRow] = useState<AdminUpstreamRow | null>(null)
  const [teams, setTeams] = useState<TeamRef[] | null>(null)
  const [products, setProducts] = useState<ProductRef[] | null>(null)
  const [roles, setRoles] = useState<RoleRef[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const { busy, run: withBusy } = useBusyAction({
    explain,
    setError,
    // a delete that hid the drawer then failed must show the error
    onError: reveal
  })

  const reload = useCallback(
    async (signal?: AbortSignal) => {
      const r = await fetchAdminUpstream(upstreamId, signal)
      if (!signal?.aborted) setRow(r)
    },
    [upstreamId]
  )

  useEffect(() => {
    const ctrl = new AbortController()
    Promise.all([
      reload(ctrl.signal),
      fetchTeams(ctrl.signal),
      fetchProducts(ctrl.signal),
      fetchRoles(ctrl.signal)
    ]).then(
      ([_, t, p, r]) => {
        if (ctrl.signal.aborted) return
        setTeams(t)
        setProducts(p)
        setRoles(r)
      },
      (err) => {
        if (!ctrl.signal.aborted) setError(explain(err))
      }
    )
    return () => ctrl.abort()
  }, [reload])

  if (!row) {
    return (
      <Drawer
        opened={!hidden}
        onClose={onClose}
        title="Loading…"
        position="right"
        size="lg"
        padding="md"
      >
        {error ? <Alert color="red">{error}</Alert> : <Text c="dimmed">Loading…</Text>}
      </Drawer>
    )
  }

  return (
    <Drawer
      opened={!hidden}
      onClose={onClose}
      title={`Upstream · ${row.displayName}`}
      position="right"
      size="lg"
      padding="md"
    >
      <Stack gap="md">
        {error && (
          <Alert color="red" variant="light" radius="sm">
            {error}
          </Alert>
        )}

        <DetailsSection
          row={row}
          busy={busy}
          onSave={(patch) =>
            withBusy(async () => {
              await adminPatchUpstream(upstreamId, patch)
              await reload()
              onChanged()
            }, 'Save')
          }
          onDelete={() =>
            withBusy(async () => {
              const ok = await confirm(
                {
                  title: 'Delete upstream?',
                  message: `Delete upstream "${row.displayName}"? All cached tools, visibility rules, and per-user credentials for this upstream will be removed.`,
                  confirmLabel: 'Delete',
                  danger: true
                },
                { keepHiddenOnConfirm: true }
              )
              if (!ok) return
              await adminDeleteUpstream(upstreamId)
              onDeleted()
            }, 'Delete')
          }
        />

        <VisibilitySection
          row={row}
          teams={teams}
          products={products}
          roles={roles}
          busy={busy}
          onSave={(rules) =>
            withBusy(async () => {
              await adminPutUpstreamVisibility(upstreamId, { rules })
              await reload()
              onChanged()
            }, 'Save visibility')
          }
        />

        <ConnectionSection
          row={row}
          busy={busy}
          onSaveBearer={(token) =>
            withBusy(async () => {
              await putUpstreamCredentials(upstreamId, { token })
              await reload()
              onChanged()
            }, 'Save bearer')
          }
          onDisconnect={() =>
            withBusy(async () => {
              const ok = await confirm({
                title: 'Disconnect upstream?',
                message: `Disconnect your credentials for "${row.displayName}"? You'll need to ${
                  row.authStrategy === 'user_oauth' ? 'reauthorize' : 'paste a new token'
                } before Refresh works again.`,
                confirmLabel: 'Disconnect',
                danger: true
              })
              if (!ok) return
              await deleteUpstreamCredentials(upstreamId)
              await reload()
              onChanged()
            }, 'Disconnect')
          }
          onSaveShared={(token) =>
            withBusy(async () => {
              await adminPutSharedCredentials(upstreamId, { token })
              await reload()
              onChanged()
            }, 'Save shared token')
          }
          onClearShared={() =>
            withBusy(async () => {
              const ok = await confirm({
                title: 'Clear shared token?',
                message: `Clear the shared token for "${row.displayName}"? Every user of this upstream loses access until a new token is configured.`,
                confirmLabel: 'Clear',
                danger: true
              })
              if (!ok) return
              await adminDeleteSharedCredentials(upstreamId)
              await reload()
              onChanged()
            }, 'Clear shared token')
          }
        />

        <ToolsCacheSection
          row={row}
          busy={busy}
          onRefresh={() =>
            withBusy(async () => {
              await adminRefreshUpstreamTools(upstreamId)
              await reload()
              onChanged()
            }, 'Refresh tools')
          }
        />

        <ToolAccessSection
          upstreamId={upstreamId}
          teams={teams}
          products={products}
          roles={roles}
        />
      </Stack>
    </Drawer>
  )
}
import { useState } from 'react'
import { Select, TextInput } from '@mantine/core'
import type { SupportedTransport } from '@ctxlayer/shared'
import { FormModalShell } from '../../../components/form-modal-shell'
import { adminCreateUpstream } from '../../../lib/api'
import { useBusyAction } from '../../../lib/use-busy'
import { useSlugSuggest } from '../../../lib/use-slug-suggest'
import {
  AUTH_OPTIONS,
  OAUTH_STATIC,
  TRANSPORT_OPTIONS,
  explain,
  persistedStrategy,
  type FormAuthStrategy
} from './helpers'
import {
  EMPTY_OAUTH_FIELDS,
  OAuthClientFields,
  buildStaticOAuth,
  type OAuthClientFieldValues
} from './OAuthClientFields'

// Conditionally mounted by the caller (`{createOpen && …}`), so all state
// resets for free on close — no `opened` prop / reset effect.
export function CreateUpstreamModal({
  onClose,
  onCreated
}: {
  onClose: () => void
  onCreated: (id: string) => void
}) {
  const [displayName, setDisplayName] = useState('')
  const slugField = useSlugSuggest('upstream', displayName)
  const [transport, setTransport] = useState<SupportedTransport>('streamable_http')
  const [url, setUrl] = useState('')
  const [authStrategy, setAuthStrategy] = useState<FormAuthStrategy>('user_bearer')
  const [oauthFields, setOauthFields] = useState<OAuthClientFieldValues>(EMPTY_OAUTH_FIELDS)
  const { busy, error, run: withBusy } = useBusyAction({ explain })

  const submit = () =>
    withBusy(async () => {
      const oauth = authStrategy === OAUTH_STATIC ? buildStaticOAuth(oauthFields) : undefined
      const created = await adminCreateUpstream({
        slug: slugField.slug.trim(),
        displayName: displayName.trim(),
        transport,
        url: url.trim(),
        authStrategy: persistedStrategy(authStrategy),
        authConfig: oauth ? { oauth } : undefined,
        enabled: true
      })
      onCreated(created.id)
    }, 'Create')

  return (
    <FormModalShell
      title="New upstream"
      size="lg"
      error={error}
      busy={busy}
      submitLabel="Create"
      submitDisabled={!slugField.slug.trim() || !displayName.trim() || !url.trim()}
      onSubmit={submit}
      onClose={onClose}
    >
      <TextInput
        label="Display name"
        placeholder="Notion"
        value={displayName}
        onChange={(e) => setDisplayName(e.currentTarget.value)}
      />
      <TextInput
        label="Slug"
        placeholder="up-notion"
        description="Used in tool namespacing — agents see up-notion__search_pages. Must start with up-, then lowercase/digits/dashes, max 24. Immutable after creation."
        value={slugField.slug}
        onChange={(e) => slugField.setSlug(e.currentTarget.value)}
      />
      <Select
        label="Transport"
        data={TRANSPORT_OPTIONS}
        value={transport}
        onChange={(v) => v && setTransport(v as SupportedTransport)}
        allowDeselect={false}
      />
      <TextInput
        label="Upstream MCP URL"
        placeholder="https://mcp.notion.com/mcp"
        value={url}
        onChange={(e) => setUrl(e.currentTarget.value)}
      />
      <Select
        label="Auth strategy"
        data={AUTH_OPTIONS.map((o) => ({
          value: o.value,
          label: o.label
        }))}
        value={authStrategy}
        onChange={(v) => v && setAuthStrategy(v as FormAuthStrategy)}
        allowDeselect={false}
        description={AUTH_OPTIONS.find((o) => o.value === authStrategy)?.description}
      />
      {authStrategy === OAUTH_STATIC && (
        <OAuthClientFields
          values={oauthFields}
          onChange={(patch) => setOauthFields((v) => ({ ...v, ...patch }))}
        />
      )}
    </FormModalShell>
  )
}
